// MaoMao: the site's finance pet, rendered from the real spiking network in
// maomao/ (see maomao/README.md for the full architecture and the credit to
// github.com/mille-okws/pestinha, the project that inspired this one).
//
// This file only reads MAOMAO_DATA (docs/assets/maomao_data.js, generated by
// docs/export_maomao.py from output/maomao_state.json — the same state
// maomao/daily.py persists after every pipeline run) and draws it. It does
// not compute any mood itself, and it never reads a predicted direction —
// see README_Errors.md ERR-013 for why that would be dishonest.

const _MAOMAO_POOLS = ['CALM', 'FEARFUL', 'EUPHORIC', 'CONFUSED'];

// Dados (MAOMAO_DATA) são neutros de idioma (números, datas); só o texto
// renderizado é traduzido, pela mesma convenção do resto do site (uma
// camada de dados, duas camadas de UI — ver docs/pt/index.html).
const _MAOMAO_I18N = {
  en: {
    petName: 'MaoMao',
    scopeNames: { portfolio: 'Portfolio', market: 'Market' },
    captions: {
      CALM:     "Been steady lately — no anomaly, no stress signal standing out.",
      FEARFUL:  "Picking up on stress — volatility, a VIX move, or a losing streak.",
      EUPHORIC: "Feeling good — sustained gains with low volatility.",
      CONFUSED: "The RF/GB/SGD models disagree a lot on direction today.",
    },
    labels: { CALM: 'Calm', FEARFUL: 'Fearful', EUPHORIC: 'Content', CONFUSED: 'Confused' },
    growing: { label: 'Still young', detail: 'No validated days yet — MaoMao needs the pipeline to run at least once.' },
    resting: (date) => `Quiet day (${date}) — nothing is standing out.`,
    activity: (pct) => `activity ${pct}%`,
    learnedTrust: (ch)    => `Has learned to trust ${ch} for this mood, from real outcomes so far.`,
    learnedDiscount: (ch) => `Has learned to discount ${ch} for this mood, from real outcomes so far.`,
    stillLearning: 'Still learning this one — no confirmed pattern yet.',
  },
  pt: {
    petName: 'MaoMao',
    scopeNames: { portfolio: 'Carteira', market: 'Mercado' },
    captions: {
      CALM:     'Tem estado estável — sem anomalia, sem sinal de stress se destacando.',
      FEARFUL:  'Captando stress — volatilidade, movimento do VIX, ou sequência de perdas.',
      EUPHORIC: 'Animado — ganhos sustentados com baixa volatilidade.',
      CONFUSED: 'Os modelos RF/GB/SGD discordam bastante na direção hoje.',
    },
    labels: { CALM: 'Calmo', FEARFUL: 'Com medo', EUPHORIC: 'Contente', CONFUSED: 'Confuso' },
    growing: { label: 'Ainda jovem', detail: 'Ainda sem dias validados — o MaoMao precisa que o pipeline rode pelo menos uma vez.' },
    resting: (date) => `Dia tranquilo (${date}) — nada se destacando.`,
    activity: (pct) => `atividade ${pct}%`,
    learnedTrust: (ch)    => `Já aprendeu a confiar em ${ch} para este humor, a partir de resultados reais até agora.`,
    learnedDiscount: (ch) => `Já aprendeu a descontar ${ch} para este humor, a partir de resultados reais até agora.`,
    stillLearning: 'Ainda aprendendo este — nenhum padrão confirmado ainda.',
  },
};

function _maomaoLearnedNote(learned, pool, t) {
  const w = (learned && learned[pool]) || {};
  const strong = Object.entries(w).filter(([, v]) => Math.abs(v) > 0.03);
  if (!strong.length) return t.stillLearning;
  strong.sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]));
  const [channel, weight] = strong[0];
  return weight > 0 ? t.learnedTrust(channel) : t.learnedDiscount(channel);
}

function computeMaoMaoMood(maomaoData, lang = 'en') {
  const t = _MAOMAO_I18N[lang] || _MAOMAO_I18N.en;
  const history = (maomaoData && maomaoData.mood_history) || [];
  if (!history.length) {
    return { mood: 'growing', label: t.growing.label, detail: t.growing.detail };
  }

  const last = history[history.length - 1];
  const rates = last.mood;
  let top = 'CALM', topVal = -1;
  for (const p of _MAOMAO_POOLS) {
    if ((rates[p] || 0) > topVal) { top = p; topVal = rates[p]; }
  }
  if (topVal < 0.05) {
    return { mood: 'calm', label: t.labels.CALM, detail: t.resting(last.date) };
  }

  const faceByPool = { CALM: 'calm', FEARFUL: 'stressed', EUPHORIC: 'improving', CONFUSED: 'declining' };
  const extra = (top === 'FEARFUL' || top === 'EUPHORIC')
    ? ' ' + _maomaoLearnedNote(maomaoData.learned, top, t)
    : '';

  return {
    mood: faceByPool[top],
    label: t.labels[top],
    detail: `${t.captions[top]} (${last.date}, ${t.activity((topVal * 100).toFixed(0))})${extra}`,
    petName: t.petName,
  };
}

// Each mood only changes eyes/brows/mouth/ears/color — same body, so the
// creature stays recognizable across states instead of looking like four
// unrelated drawings.
